    const factRows=new Map(),sameFact=(a,b)=>JSON.stringify([a.content,[...a.knows].sort(),[...a.doesNotKnow].sort()])===JSON.stringify([b.content,[...b.knows].sort(),[...b.doesNotKnow].sort()]);
