    const base=String(title|| (group==='character'?'캐릭터':'기타')).trim()||(group==='character'?'캐릭터':'기타');
    if(!used.has(roomCopyCanonical(base)))return base;
    for(let n=2;n<10000;n++){const next=`${base} (복사 ${n})`;if(!used.has(roomCopyCanonical(next)))return next;}
