    target.state.knowledge=target.state.knowledge&&typeof target.state.knowledge==='object'?target.state.knowledge:{};target.state.concealments=Array.isArray(target.state.concealments)?target.state.concealments:[];target.state.present=Array.isArray(target.state.present)?target.state.present:[];
