      if(!entry.enabled||entry.type==='speech'||entry.speechRule)continue;
      const item=makeLorePendingItem({pack,entry,anchor:entry.anchor===true,score:0,keywordScore:0,semanticScore:0,matchedTrigger:'',matchedTerms:[]},'full');
      if(item.content){item.recallReason=entry.anchor?'앵커 · 항상 참고':'한도 내 전체 포함 · 관련도 계산 안 함';rows.push(item);}
