    w.innerHTML = '<button type="button" class="wish-mon-core" title="탭: 짬통 매니저 열기 · 길게: 현재 주입" aria-label="짬통 매니저 — 탭하여 전체 패널 열기, 길게 눌러 현재 주입 보기"><svg class="wish-mon-hold" viewBox="0 0 40 40"><circle cx="20" cy="20" r="18"/></svg><span class="wish-mon-spin"></span><svg class="wish-mon-gauge" viewBox="0 0 32 32"><circle class="trk" cx="16" cy="16" r="13"/><circle class="val" cx="16" cy="16" r="13"/></svg><b>–</b><span class="wish-mon-badge" hidden></span></button>';
