 if(next.delta||next.index)await WishEconomy.backup(room);
 if(state.currentRoom!==room||epoch!==localRestoreEpoch)throw Error('방 또는 복원 상태가 바뀌었습니다.');
 saveAiSettings({...loadAiSettings(),apiEconomy:next});
