                    if(ack.contextInitializedAfter)slot.contextInitialized=true;
                    slot.lastSyncAt=Math.max(Number(slot.lastSyncAt||0),Number(ack.submittedAt||Date.now()));
                    slot.baselineLease=cgcComputeLease(slot,getSettings());
