            const hasDraft=()=>{const el=composer();return !el||Boolean(String('value' in el?el.value:(el.innerText||el.textContent||'')).replace(/[\s\u034f\u061c\u180e\u200b-\u200f\u202a-\u202e\u2060-\u206f\ufeff]/g,''));};
